99:                             // present (even for non-split kernels, which never read it) --
100:                             // see python/igemm/igemm_wrw_gtc_wmma_nhwc.py's karg comment.
101:    int   gemm_k_tail;         // Phase 35: wmma_k_tail remainder R = gemm_k - num_k_blocks*
102:                                // gemm_k_per_block. Always present in this C++ struct (same
103:                                // "always present" convention as gemm_k_per_wg above), but
104:                                // only declared/read on the device side when wmma_k_tail AND
105:                                // gemm_k_global_split are both set -- see get_kernel_args().
106:    int   gemm_k_num_splits;   // Phase 35: the launched grid.z (== splits), so the device can
107:                                // tell "am I the last shard" via bz == gemm_k_num_splits-1.
108:                                // Phase 58 (wrw_streamk): reused as "total shard count" for
109:                                // the persistent loop's in-range test (same meaning, offset
110:                                // 96 either way -- see get_kernel_args()'s Phase 58 note).
111:    int   _streamk_pad;        // Phase 58: this struct is `packed` (no compiler-inserted
112:                                // padding) -- without an explicit 4-byte filler here,
113:                                // p_streamk_counter would land at byte offset 100 (NOT
114:                                // 8-aligned), but the device emits `s_load_dwordx2` for it
115:                                // (get_kernel_args() declares it at offset 104). Only present
116:                                // when wrw_streamk is set device-side; host always carries it
117:                                // (same "always present" convention as every other field here).
118:    void *p_streamk_counter;   // Phase 58: pointer to a host-zeroed grid_x*grid_y*4-byte
119:                                // int32 workspace, one atomic-claim counter per output tile.
120:                                // Only present/read when wrw_streamk is set.
121:    int   streamk_max_iters;   // Phase 58: this persistent workgroup's bounded loop trip
122:                                // count = ceil(total_shards / launched_grid_z).
123:    int   streamk_grid_y;      // Phase 58: grid.y (N-block count), for this tile's counter
124:                                // index = (bx*grid_y + by).
125:    // Phase 60 (Magic Division): host-computed magic multipliers for the ho_wo/wo
126:    // divisors in _emit_b_gather_one_row's K-decomposition. Always present.
