157:class igemm_wrw_gtc_t : public igemm_driver_base_t {
158:public:
159:    igemm_wrw_gtc_t(hipModule_t module_tensor_cast_, hipModule_t module_, driver_mode_t driver_mode_, driverDataType_t data_type_, int warmup_, int repeat_, bool verbose_)
160:        : igemm_driver_base_t(module_tensor_cast_, module_, driver_mode_, data_type_, warmup_, repeat_, verbose_) {}
161:    ~igemm_wrw_gtc_t(){}
162:
163:    size_t get_block_size(const igemm_gtc_tunable_t *tunable) override {
164:        if(tunable->fma_type == IGEMM_GTC_TUNABLE_FMA_TYPE_MAC || tunable->fma_type == IGEMM_GTC_TUNABLE_FMA_TYPE_DLOPS){
165:            return tunable->gemm_m_level0_cluster * tunable->gemm_n_level0_cluster *
166:               tunable->gemm_m_level1_cluster * tunable->gemm_n_level1_cluster;
167:        }
168:        else if(tunable->fma_type == IGEMM_GTC_TUNABLE_FMA_TYPE_XDLOPS){
169:            int waves_per_m = tunable->gemm_m_per_block / (tunable->wave_tile_m * tunable->wave_step_m * tunable->wave_repeat_m);
170:            int waves_per_n = tunable->gemm_n_per_block / (tunable->wave_tile_n * tunable->wave_step_n * tunable->wave_repeat_n);
171:            return waves_per_m * waves_per_n * AMDGPU_WAVE_SIZE;
172:        }
173:        else if(tunable->fma_type == IGEMM_GTC_TUNABLE_FMA_TYPE_WMMA){
174:            int waves_per_m = tunable->gemm_m_per_block / (tunable->wave_tile_m * tunable->wave_repeat_m);
175:            int waves_per_n = tunable->gemm_n_per_block / (tunable->wave_tile_n * tunable->wave_repeat_n);
176:            return waves_per_m * waves_per_n * 32;
177:        }
178:        else{
179:            std::cout << "not valid fma_type: " << tunable->fma_type << std::endl;
180:            assert(false);
181:            return 0;
182:        }
183:    }
184:    size_t get_grid_size(const args_t *arg,
185:                      const igemm_gtc_tunable_t *tunable) override {
186:        int hi = arg->get_int("in_h");
187:        int wi = arg->get_int("in_w");
188:        int n = arg->get_int("batchsize");
189:        int k = arg->get_int("out_channels");
190:        int c = arg->get_int("in_channels");
191:
192:        int stride_h = arg->get_int("conv_stride_h");
193:        int stride_w = arg->get_int("conv_stride_w");
194:        int dilation_h = arg->get_int("dilation_h");
195:        int dilation_w = arg->get_int("dilation_w");
196:        int pad_h = arg->get_int("pad_h");
197:        int pad_w = arg->get_int("pad_w");
198:        int y = arg->get_int("fil_h");
199:        int x = arg->get_int("fil_w");
200:        int ho = conv_out_size(hi, pad_h, dilation_h, y, stride_h);
201:        int wo = conv_out_size(wi, pad_w, dilation_w, x, stride_w);
202:        int group = arg->get_int("group_count");
203:
204:        int gemm_m_per_block         = tunable->gemm_m_per_block;
205:        int gemm_n_per_block         = tunable->gemm_n_per_block;
206:        int gemm_k_per_block         = tunable->gemm_k_per_block;
207:        int gemm_k_global_split      = tunable->gemm_k_global_split;
208:		
209:        int block_size               = get_block_size(tunable);
210:        int c_vec_min                = tunable->tensor_layout == "nchw" ? 1 : (tunable->tensor_b_thread_lengths[3]);
211:        int max_grid_size            = 1200;
212:
213:        int gemm_m = k / group;
214:        int c_padded = ((c / group) + c_vec_min - 1) / c_vec_min * c_vec_min;
215:        int gemm_n = (c_padded * y * x  + gemm_n_per_block - 1) / gemm_n_per_block * gemm_n_per_block;
216:        size_t grid_size = static_cast<size_t>(group) * utility_integer_divide_ceil(gemm_m, gemm_m_per_block) *
217:                                    utility_integer_divide_ceil(gemm_n, gemm_n_per_block);
218:
219:        int splits = igemm_split_batch_size(arg, utility_string_to_data_byte(tunable->precision));
220:        if(splits == 0){
221:            printf("image size (c*h*w or k*h*w) is bigger than 4g, which is not supported now\n");
222:            return false;
223:        }
224:        n = n/splits;   // split batch size here
225:
226:        int min_n_per_block = 1;
227:        if(tunable->tensor_layout == "nhwc" && tunable->nxe == 1)
228:            min_n_per_block = tunable->tensor_a_thread_lengths[1];
229:
230:        int b = ho * wo;
231:        if(tunable->tensor_layout == "nchw")
232:            b = tunable->nxe == 0 ? (ho * wo) : ((ho * wo + tunable->nxb - 1) / tunable->nxb) * tunable->nxb;
233:
234:        if(tunable->tensor_layout == "nchw"){
235:            int gemm_k_global_splits = gemm_k_global_split == 1 ? compute_log2_gemmk_global_splits(grid_size, max_grid_size, n / min_n_per_block, b, gemm_k_per_block)
236:                                                                 : 0;
237:
238:            int num_of_gemm = 1 << gemm_k_global_splits;
239:            grid_size *= num_of_gemm;
240:        }
241:
242:        assert(grid_size <= 0xffffffffUL);
243:        return grid_size;
244:    }
245:
246:    int get_lds_size(const igemm_gtc_tunable_t *tunable) {
247:        // TODO: fp16/bf16, xdlops
248:        int lds_a = utility_string_to_data_byte(tunable->precision) * tunable->gemm_k_per_block * tunable->gemm_m_per_block;
249:        int lds_b = utility_string_to_data_byte(tunable->precision) * tunable->gemm_k_per_block * tunable->gemm_n_per_block;
250:        return 2 * utility_next_pow2(utility_next_pow2(lds_a) + utility_next_pow2(lds_b));
251:    }
