272:        int wo = conv_out_size(wi, pad_w, dilation_w, x, stride_w);
273:        int group = arg->get_int("group_count");
274:		int forw = arg->get_int("forw");
275:
276:        int need_wrw = (forw == 0 ? 1 : (forw & 4 ? 1 : 0));
277:        if(need_wrw == 0)
278:            return false;
279:
280:        if(tunable->fma_type == IGEMM_GTC_TUNABLE_FMA_TYPE_WMMA){
281:            // igemm_wrw_gtc_wmma_nhwc_t requires a single fixed 128x128 macro-tile shape --
282:            // see igemm_fwd_gtc_driver.h's identical WMMA branch for the rationale. Phase 5c
283:            // added arbitrary stride/pad, Phase 5f added arbitrary y/x (multi-tap filters) and
284:            // dilation, Phase 7 added group>1. Checked here, BEFORE the fil_h_ext/pad sanity
285:            // check below: that check assumes the general kernel's addressing (padding >= a
286:            // 1x1 filter's extent-of-1 is nonsensical for it) and would incorrectly reject
287:            // every padded WMMA config, which this kernel's gather+mask mechanism handles
288:            // correctly regardless of filter size.
289:            if(tunable->tensor_layout != "nhwc")
290:                return false;
291:            if(group < 1 || c % group != 0 || k % group != 0)
292:                return false;
293:            int wmma_gemm_m = k / group;
294:            int wmma_gemm_n = c / group;
295:            int wmma_gemm_k = n * ho * wo;
296:            // Phase 35: wmma_m_tail/wmma_n_tail/wmma_k_tail each independently relax their own
297:            // axis's exact-multiple requirement -- mirrors fwd's identical relax pattern in
298:            // igemm_fwd_gtc_driver.h. Unlike fwd/bwd, wrw's M/N-tail must also work under
299:            // gemm_k_global_split (checked/asserted at the tunable-construction level in
