14:    num_tiles_         = integer_divide_ceil(m, MPerBlock) * integer_divide_ceil(n_, NPerBlock);
15:    remainder_along_k_ = k % KPerBlock;
16:
17:    bool big_enough         = num_tiles_ > max_active_wgs_;
18:    index_t remainder_tiles = num_tiles_ % max_active_wgs_;
19:
20:    if(remainder_tiles)
21:    {
22:        sk_tiles_ = big_enough ? full_tiles_ * max_active_wgs_ + (num_tiles_ % max_active_wgs_)
23:                               : num_tiles_;
24:        sk_tiles_ = min(num_tiles_, sk_tiles_);
25:        sk_ctas_  = max_active_wgs_;
26:        total_sk_iters_ = sk_tiles_ * iters_per_tile_;
27:
28:        // If there still isn't enough work to saturate all CUs, then just revert to DP only.
29:        if(total_sk_iters_ < max_active_wgs_)
30:        {
31:            sk_tiles_       = 0;
32:            sk_ctas_        = 0;
33:            total_sk_iters_ = 0;
34:        }
35:    }
36:    else // Full DP (i.e., no Stream-K)
37:    {
